package demo.tickets.events;

import jakarta.validation.Valid;
import java.util.OptionalLong;
import java.util.regex.Pattern;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/events/{id}")
public class EventDetailsController {

    private static final Pattern STRONG_VERSION_TAG = Pattern.compile("\"(\\d{1,18})\"");

    private final EventDetailsService service;

    public EventDetailsController(EventDetailsService service) {
        this.service = service;
    }

    @GetMapping
    public ResponseEntity<EventDetails> get(@PathVariable long id) {
        var event = service.find(id);
        return ResponseEntity.ok().eTag(Long.toString(event.version())).body(event);
    }

    @PutMapping
    public ResponseEntity<EventDetails> update(@PathVariable long id,
            @RequestHeader(name = HttpHeaders.IF_MATCH, required = false) String ifMatch,
            @Valid @RequestBody EventDetailsChange change) {
        if (ifMatch == null) {
            return ResponseEntity.status(HttpStatus.PRECONDITION_REQUIRED).build();
        }
        var expectedVersion = versionOf(ifMatch);
        if (expectedVersion.isEmpty()) {
            return ResponseEntity.status(HttpStatus.PRECONDITION_FAILED).build();
        }
        var updated = service.update(id, expectedVersion.getAsLong(), change);
        return ResponseEntity.ok().eTag(Long.toString(updated.version())).body(updated);
    }

    private static OptionalLong versionOf(String ifMatch) {
        var matcher = STRONG_VERSION_TAG.matcher(ifMatch.strip());
        return matcher.matches() ? OptionalLong.of(Long.parseLong(matcher.group(1))) : OptionalLong.empty();
    }
}

