    }

    public int update(long id, long expectedVersion, EventDetailsChange change) {
        return jdbc.sql("""
                UPDATE events
                SET title = :title, description = :description, venue = :venue,
                    starts_at = :startsAt, version = version + 1
                WHERE id = :id AND version = :expectedVersion""")
                .param("title", change.title())
                .param("description", change.description())
                .param("venue", change.venue())
                .param("startsAt", change.startsAt().atOffset(ZoneOffset.UTC))
