package demo.tickets.events;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class EventDetailsService {

    private final EventDetailsRepository repository;

    public EventDetailsService(EventDetailsRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public EventDetails find(long id) {
        return repository.find(id).orElseThrow(() -> new UnknownEventException(id));
    }

    @Transactional
    public EventDetails update(long id, long expectedVersion, EventDetailsChange change) {
        if (repository.update(id, expectedVersion, change) == 0) {
            if (!repository.exists(id)) {
                throw new UnknownEventException(id);
            }
            throw new StaleEventException(id, expectedVersion);
        }
        return repository.find(id).orElseThrow();
    }
}

