package demo.tickets.orders;

import demo.tickets.events.UnknownEventException;
import java.time.Clock;
import java.time.ZoneOffset;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TicketPurchaseService {

    private final JdbcClient jdbc;
    private final Clock clock;

    public TicketPurchaseService(JdbcClient jdbc, Clock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    @Transactional
    public long purchase(long eventId, String customerEmail, int quantity) {
        int ticketsLeft = jdbc.sql("SELECT tickets_left FROM event_inventory WHERE event_id = :eventId")
                .param("eventId", eventId)
                .query(Integer.class)
                .optional()
                .orElseThrow(() -> new UnknownEventException(eventId));
        if (ticketsLeft < quantity) {
            throw new SoldOutException(eventId);
        }
        jdbc.sql("UPDATE event_inventory SET tickets_left = :ticketsLeft WHERE event_id = :eventId")
                .param("ticketsLeft", ticketsLeft - quantity)
                .param("eventId", eventId)
                .update();
        return jdbc.sql("""
                INSERT INTO orders (event_id, customer_email, quantity, created_at)
                VALUES (:eventId, :customerEmail, :quantity, :createdAt)
                RETURNING id""")
                .param("eventId", eventId)
                .param("customerEmail", customerEmail)
                .param("quantity", quantity)
                .param("createdAt", clock.instant().atOffset(ZoneOffset.UTC))
                .query(Long.class)
                .single();
    }
}

