package demo.tickets.reminders;

import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneId;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClientException;

@Component
public class ReminderJob {

    private static final Logger log = LoggerFactory.getLogger(ReminderJob.class);
    private static final ZoneId VENUE_ZONE = ZoneId.of("Europe/Zurich");

    private final ReminderRepository reminders;
    private final ReminderMailer mailer;
    private final Clock clock;

    public ReminderJob(ReminderRepository reminders, ReminderMailer mailer, Clock clock) {
        this.reminders = reminders;
        this.mailer = mailer;
        this.clock = clock;
    }

    @Scheduled(cron = "0 0 9 * * *", zone = "Europe/Zurich")
    public void sendReminders() {
        LocalDate tomorrow = LocalDate.now(clock.withZone(VENUE_ZONE)).plusDays(1);
        int sent = 0;
        for (Reminder reminder : reminders.dueFor(tomorrow, VENUE_ZONE)) {
            try {
                mailer.send(reminder);
                reminders.markSent(reminder.orderId(), clock.instant());
                sent++;
            } catch (RestClientException e) {
                log.warn("Reminder for order {} not sent", reminder.orderId(), e);
            }
        }
        log.info("Sent {} reminders for events on {}", sent, tomorrow);
    }
}

