package demo.tickets.reminders;

import java.time.Instant;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.List;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class ReminderRepository {

    private final JdbcClient jdbc;

    public ReminderRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public List<Reminder> dueFor(LocalDate eventDate, ZoneId zone) {
        return jdbc.sql("""
                SELECT o.id, o.customer_email, e.title, e.starts_at
                FROM orders o
                JOIN events e ON e.id = o.event_id
                WHERE e.starts_at >= :from AND e.starts_at < :to
                  AND o.reminder_sent_at IS NULL
                ORDER BY o.id""")
                .param("from", eventDate.atStartOfDay(zone).toOffsetDateTime())
                .param("to", eventDate.plusDays(1).atStartOfDay(zone).toOffsetDateTime())
                .query((rs, n) -> new Reminder(rs.getLong("id"), rs.getString("customer_email"),
                        rs.getString("title"), rs.getObject("starts_at", OffsetDateTime.class).toInstant()))
                .list();
    }

    public void markSent(long orderId, Instant sentAt) {
        jdbc.sql("UPDATE orders SET reminder_sent_at = :sentAt WHERE id = :orderId")
                .param("sentAt", sentAt.atOffset(ZoneOffset.UTC))
                .param("orderId", orderId)
                .update();
    }
}

