package demo.boxoffice.orders;

import demo.boxoffice.events.UnknownEventException;
import java.time.Clock;
import java.time.ZoneOffset;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class CounterSaleService {

    private final JdbcClient jdbc;
    private final Clock clock;

    public CounterSaleService(JdbcClient jdbc, Clock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    @Transactional
    public long sell(long eventId, String customerEmail, int quantity) {
        int reserved = jdbc.sql("""
                UPDATE event_inventory
                SET tickets_left = tickets_left - :quantity
                WHERE event_id = :eventId AND tickets_left >= :quantity""")
                .param("quantity", quantity)
                .param("eventId", eventId)
                .update();
        if (reserved == 0) {
            boolean known = jdbc.sql("SELECT EXISTS (SELECT 1 FROM event_inventory WHERE event_id = :eventId)")
                    .param("eventId", eventId)
                    .query(Boolean.class)
                    .single();
            throw known ? new SoldOutException(eventId) : new UnknownEventException(eventId);
        }
        return jdbc.sql("""
                INSERT INTO orders (event_id, customer_email, quantity, created_at)
                VALUES (:eventId, :customerEmail, :quantity, :createdAt)
                RETURNING id""")
                .param("eventId", eventId)
                .param("customerEmail", customerEmail)
                .param("quantity", quantity)
                .param("createdAt", clock.instant().atOffset(ZoneOffset.UTC))
                .query(Long.class)
                .single();
    }
}

