    private final Clock clock;

    public ReminderJob(ReminderRepository reminders, ReminderMailer mailer, Clock clock) {
        this.reminders = reminders;
        this.mailer = mailer;
        this.clock = clock;
    }

    @Scheduled(cron = "0 0 9 * * *", zone = "Europe/Zurich")
    public void sendReminders() {
        LocalDate tomorrow = LocalDate.now(clock.withZone(VENUE_ZONE)).plusDays(1);
        int sent = 0;
        for (Reminder reminder : reminders.dueFor(tomorrow, VENUE_ZONE)) {
            try {
                mailer.send(reminder);
                reminders.markSent(reminder.orderId(), clock.instant());
                sent++;
            } catch (RestClientException e) {
                log.warn("Reminder for order {} not sent", reminder.orderId(), e);
            }
        }
        log.info("Sent {} reminders for events on {}", sent, tomorrow);
    }
}

package demo.boxoffice.reminders;

public interface ReminderMailer {

    void send(Reminder reminder);
